"""Build inspectable standalone HTML templates and their proposed JSON contracts."""
from pathlib import Path
import json
from dense_templates import DENSE_TEMPLATES

ROOT = Path(__file__).resolve().parent

def diagram():
    return '''<svg class="diagram" viewBox="0 0 620 390" role="img" aria-label="Illustrative tank diagram: containment, liquid level and vapour space">
    <defs><linearGradient id="tank-fill" x2="0" y2="1"><stop stop-color="#173d58"/><stop offset="1" stop-color="#0e2b43"/></linearGradient><clipPath id="tank-clip"><rect x="62" y="94" width="496" height="228" rx="69"/></clipPath></defs>
    <path d="M180 323v22m260-22v22M154 346h52m208 0h52" fill="none" stroke="#69869c" stroke-width="8" stroke-linecap="round"/>
    <rect x="57" y="89" width="506" height="238" rx="74" fill="url(#tank-fill)" stroke="#8baac0" stroke-width="3"/>
    <g clip-path="url(#tank-clip)"><path d="M58 224 Q90 211 122 224T186 224T250 224T314 224T378 224T442 224T506 224T570 224V328H58Z" fill="#247fa8" opacity=".75"/><path d="M58 238h505M58 265h505M58 292h505" stroke="#58b7da" stroke-opacity=".18" stroke-width="1"/></g>
    <path d="M310 89V52h104" fill="none" stroke="#7b99af" stroke-width="7" stroke-linejoin="round"/>
    <circle cx="414" cy="52" r="15" fill="#122c44" stroke="#8baac0" stroke-width="2"/><path d="M414 52l7-6" stroke="#e9ab39" stroke-width="2"/>
    <path d="M105 169h410" stroke="#8baac0" stroke-dasharray="4 8" stroke-opacity=".35"/>
    <text x="310" y="154" fill="#9ab7cb" text-anchor="middle" font-size="15" letter-spacing="4">VAPOUR SPACE</text>
    <text x="310" y="282" fill="#c3e6f3" text-anchor="middle" font-size="16" letter-spacing="4">LIQUID</text>
    <g data-highlight="1"><path d="M81 95L43 45H13" fill="none" stroke="#e9ab39" stroke-width="2"/><circle class="marker" cx="81" cy="95" r="5"/><text x="14" y="30" fill="#f4cf85" font-size="14" letter-spacing="1.5">01 · CONTAINMENT</text></g>
    <g data-highlight="2"><path d="M540 224h48v48" fill="none" stroke="#e9ab39" stroke-width="2"/><circle class="marker" cx="540" cy="224" r="5"/><text x="602" y="300" fill="#f4cf85" text-anchor="end" font-size="14" letter-spacing="1.5">02 · LEVEL</text></g>
    <g data-highlight="3"><path d="M492 118v-70h100" fill="none" stroke="#e9ab39" stroke-width="2"/><circle class="marker" cx="492" cy="118" r="5"/><text x="602" y="31" fill="#f4cf85" text-anchor="end" font-size="14" letter-spacing="1.5">03 · VAPOUR</text></g>
    </svg>'''

def controls():
    return '''<div class="step-controls" data-slot="figureControls"><span class="step-name" data-step-name aria-live="polite">01 / Containment</span><div class="buttons" aria-label="Figure step"><button type="button" data-control-id="figure-step-1" data-step-button="1" aria-pressed="true" aria-label="Show containment">1</button><button type="button" data-control-id="figure-step-2" data-step-button="2" aria-pressed="false" aria-label="Show liquid level">2</button><button type="button" data-control-id="figure-step-3" data-step-button="3" aria-pressed="false" aria-label="Show vapour space">3</button></div></div>'''

def panel():
    return '<div class="figure-panel" data-slot="figure"><div class="figure-caption"><span>System overview</span><span>Illustrative diagram</span></div>'+diagram()+controls()+'</div>'

stress='<p class="stress-copy" data-slot="extra">A longer explanation adds context to the same idea. This preview keeps the original font size so you can see whether the available space still supports the content comfortably.</p>'

items=[
  dict(id='explain-figure',name='Teksts + figūra',en='Explain with a figure',desc='Viena doma, skaidrojums un dominējoša figūra.',kind='explain',dark=False,slots=['eyebrow','title','points','figure','figureControls'],body='''<div class="copy"><p class="eyebrow" data-slot="eyebrow">01 / Understand the system</p><h1 data-slot="title">One system.<br>Three things to notice.</h1><p class="subhead" data-slot="lead">A clear diagram makes the relationship visible.</p><ol class="numbered" data-slot="points"><li><span class="num">01</span><span><b>See the whole.</b><br>Start with the main shape.</span></li><li><span class="num">02</span><span><b>Find the parts.</b><br>Connect each label to its place.</span></li><li data-optional><span class="num">03</span><span><b>Explain the relationship.</b><br>Use the picture to tell the story.</span></li></ol>'''+stress+'</div>'+panel()),
  dict(id='figure-stage',name='Liela figūra',en='Let the figure lead',desc='Vairāk vietas figūrai, mazāk teksta. Soļi vienmēr zem tās.',kind='stage',dark=True,slots=['title','figure','figureControls','caption'],body='''<div class="title-row"><div><p class="eyebrow">02 / Explore the detail</p><h1 data-slot="title">Let the system explain itself.</h1></div><p class="small-note" data-slot="caption">Three points of focus.<br>One shared visual.</p></div>'''+panel()+stress),
  dict(id='photo-explain',name='Foto + skaidrojums',en='Connect it to the real world',desc='Foto saglabā savu vietu, teksts paliek lasāms.',kind='photo-layout',dark=True,slots=['title','lead','points','photo','photoCredit'],body='''<div class="copy"><p class="eyebrow">03 / Recognise it on board</p><h1 data-slot="title">From the diagram<br>to the real vessel.</h1><p class="subhead" data-slot="lead">Make the connection between a simplified drawing and what you see on board.</p><ol class="numbered" data-slot="points"><li><span class="num">01</span><span><b>Recognise the shape.</b><br>Look for the main equipment.</span></li><li data-optional><span class="num">02</span><span><b>Connect the views.</b><br>Return to the diagram and compare.</span></li></ol>'''+stress+'''</div><figure class="photo-frame" data-slot="photo"><img src="../../assets/maritime-preview.jpg" alt="Generated illustrative image of a gas carrier at sea"><span class="photo-tag">ON BOARD / VISUAL CONTEXT</span><figcaption data-slot="photoCredit">AI-generated image · design preview</figcaption></figure>'''),
  dict(id='compare-two',name='Salīdzinājums',en='Compare two views',desc='Divi līdzvērtīgi bloki ar vienādu informācijas hierarhiju.',kind='compare',dark=False,slots=['title','leftMedia','leftTitle','leftText','rightMedia','rightTitle','rightText'],body='''<p class="eyebrow">04 / Make the connection</p><h1 data-slot="title">Two views. One understanding.</h1><div class="compare-grid"><article class="compare-card"><div class="compare-visual" data-slot="leftMedia">'''+diagram()+'''</div><div class="compare-copy"><p class="eyebrow">THE DIAGRAM</p><h2 data-slot="leftTitle">Understand the relationship.</h2><p data-slot="leftText">Remove the visual noise. See the main elements and how they connect.</p></div></article><article class="compare-card"><div class="compare-visual" data-slot="rightMedia"><img src="../../assets/maritime-preview.jpg" alt="Illustrative gas carrier"></div><div class="compare-copy"><p class="eyebrow">THE REAL-WORLD VIEW</p><h2 data-slot="rightTitle">Recognise the equipment.</h2><p data-slot="rightText">Add context. Find the same elements in a realistic view of the vessel.</p></div></article></div><p class="compare-note" data-optional>Use the same comparison criteria on both sides.</p>'''+stress),
  dict(id='procedure',name='Darbību secība',en='One step at a time',desc='Skaidra secība un viens aktīvais solis. Noklikšķini uz soļiem.',kind='procedure',dark=False,slots=['title','steps','activeStepTitle','activeStepText'],body='''<p class="eyebrow">05 / Follow the sequence</p><h1 data-slot="title">A clear path to understanding.</h1><div class="procedure-grid"><ol class="process-list" data-slot="steps">'''+''.join(f'<li><button type="button" data-control-id="process-step-{i}" data-process="{i}" aria-pressed="{str(i==1).lower()}"><span class="circle">{i:02}</span><span>{name}</span></button></li>' for i,name in enumerate(['Observe','Identify','Explain','Check'],1))+'''</ol><article class="process-detail" aria-live="polite"><div><span class="big-number" id="process-number">01</span><h2 id="process-title" data-slot="activeStepTitle">Observe</h2><p id="process-text" data-slot="activeStepText">Start with the whole picture. Notice the shape, the main elements and their positions.</p>'''+stress+'''</div><div class="detail-foot" id="process-foot">One clear action per step.</div></article></div>'''),
  dict(id='task-launch',name='Uzdevuma atvērums',en='Make the next action obvious',desc='Uzdevuma kods, skaidrs mērķis un īsa instrukcija.',kind='activity',dark=True,slots=['taskCode','title','instruction','taskMeta'],body='''<div class="activity-layout"><div class="activity-code" data-slot="taskCode">SC1<small>SELF-CHECK / INDIVIDUAL</small></div><div><p class="eyebrow">06 / Your turn</p><h1 data-slot="title">Read the system.</h1><p data-slot="instruction">Use the diagram to identify the main elements and explain how they relate.</p><div class="task-meta" data-slot="taskMeta"><span>3 questions</span><span>5 minutes</span><span>Individual</span></div>'''+stress+'''<button class="task-button" type="button" id="task-demo-button" data-control-id="task-preview"><span>Preview interaction</span><span aria-hidden="true">↗</span></button><div class="task-demo" id="task-demo-result" aria-live="polite"></div></div></div>'''),
  dict(id='recap',name='Kopsavilkums',en='Leave with four clear ideas',desc='Viens kopīgs noslēguma dizains visiem moduļiem.',kind='recap',dark=True,slots=['title','takeaways','nextLabel'],body='''<p class="eyebrow">07 / What to take away</p><h1 data-slot="title">The ideas that stay with you.</h1><div class="recap-grid" data-slot="takeaways">'''+''.join(f'<article class="recap-card"><span class="index">{i:02}</span><h2>{title}</h2><p>{copy}</p></article>' for i,(title,copy) in enumerate([('Start with the whole.','See the overall system before focusing on a detail.'),('Know what you are looking at.','Match each label to the element it names.'),('Connect the views.','Use the diagram and photograph together.'),('Explain it in your own words.','Turn recognition into a clear explanation.')],1))+'''</div><div class="recap-next" data-slot="nextLabel"><span>Keep these ideas in mind.</span><b>Next / Module check →</b></div>'''+stress),
  dict(id='opening',name='Moduļa atvērums',en='Open with one strong thought',desc='Liels virsraksts, viens jautājums un foto ar skaidru fokusu.',kind='opening-content',dark=True,slots=['eyebrow','title','lead','moduleMeta','backgroundImage'],body='''<p class="eyebrow" data-slot="eyebrow">MODULE 01 / SEE THE SYSTEM</p><h1 data-slot="title">Understand<br>what you see.</h1><p class="subhead" data-slot="lead">From a clear diagram to the real world.<br>One connection at a time.</p><div class="module-pill" data-slot="moduleMeta"><span>GAS FUELLED SHIPS</span><span>FOUNDATIONS</span></div>'''+stress),
]

items.extend(DENSE_TEMPLATES)
total = len(items)
for index,item in enumerate(items,1):
    directory=ROOT/'templates'/item['id'];directory.mkdir(parents=True,exist_ok=True)
    classes=('dark ' if item['dark'] else '')+('opening' if item['id']=='opening' else '')
    markup=f'''<!doctype html>
<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{item['en']} · Template preview</title><link rel="stylesheet" href="../../assets/template.css"></head>
<body data-template="{item['id']}"><main id="slide" class="{classes.strip()}" aria-label="{item['en']}">
{'<div class="hero-image" data-slot="backgroundImage" aria-hidden="true"></div>' if item['id']=='opening' else ''}
<header class="topline"><span>M01 / GAS FUELLED SHIPS</span><span class="brand">NOVIKONTAS<span> /</span></span></header>
<section class="slide-content {item['kind']}">{item['body']}</section>
<footer class="bottomline"><span>Foundation / Visual learning</span><span class="progress">{''.join('<i'+(' class="on"' if n<=index else '')+'></i>' for n in range(1,total+1))}<span style="margin-left:15px">{index:02} / {total:02}</span></span></footer>
</main><script src="../../assets/preview-runtime.js"></script></body></html>'''
    (directory/'template.html').write_text(markup)
    contract=dict(id=item['id']+'.v1',status='design-preview-not-compiler-integrated',name=item['name'],entry='template.html',logicalViewport=dict(width=1280,height=800),scaling='uniform-contain',slots=[dict(name=s,required=True) for s in item['slots']],allowedExtras=[],overflowPolicy='report-do-not-shrink-text',contentChanges='require-source-approval',assets=['../../assets/template.css','../../assets/preview-runtime.js','../../assets/raleway-variable.ttf'],notes='Proposed contract. Current preview supplies sample content; production slot binding and compiler validation are not implemented.')
    if item['id']=='content-in-parts':
        contract['state']={'part':{'type':'integer','minimum':1,'maximum':3,'initial':1}}
        contract['navigation']={'mode':'set-part','controls':'stable data-control-id','preserveAllSourceText':True,'remoteSyncImplemented':False}
    contract['visualPolicy']={'maxConsecutiveTextOnlySlides':2,'denseContentRequiresAdjacentVisual':True,'isDenseContent':item in DENSE_TEMPLATES,'sequenceValidationImplemented':False}
    if item in DENSE_TEMPLATES:
        contract['contentBalance']={'textShare':0.55,'visualShare':0.45,'textShareRange':[0.50,0.60],'visualShareRange':[0.40,0.50],'overflow':'use-more-parts-not-smaller-fonts'}
    if item['id'] in ('photo-explain','compare-two','opening'):contract['assets'].append('../../assets/maritime-preview.jpg')
    (directory/'template.json').write_text(json.dumps(contract,ensure_ascii=False,indent=2)+'\n')

catalog=[dict(id=x['id'],name=x['name'],en=x['en'],description=x['desc'],path='templates/'+x['id']+'/template.html',contract='templates/'+x['id']+'/template.json') for x in items]
(ROOT/'catalog.json').write_text(json.dumps(catalog,ensure_ascii=False,indent=2)+'\n')
(ROOT/'assets/catalog.js').write_text('window.TEMPLATE_CATALOG='+json.dumps(catalog,ensure_ascii=False)+';\n')
(ROOT/'course-layout-rules.json').write_text(json.dumps({'status':'proposed-not-compiler-enforced','maxConsecutiveTextOnlySlides':2,'denseContentRequiresAdjacentVisual':True,'splitBalance':{'textShareRange':[0.5,0.6],'visualShareRange':[0.4,0.5],'default':[0.55,0.45]},'allowedVisuals':['image','diagram','animation','interactive','model_3d'],'overflowPolicy':'paginate-approved-content-or-choose-another-template','textOnlyPolicy':'short-content-only','notes':'Course sequence must be validated by the compiler. This gallery is a template catalogue, not a course sequence. Dense preview layouts always include an adjacent visual.'},ensure_ascii=False,indent=2)+'\n')
print('Built',len(items),'HTML templates and JSON contracts.')
